#!/usr/bin/env python3
"""Build a standalone, accessible census table from the release manifest."""
import html,json,posixpath,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
 d=json.loads((ROOT/'results/census.json').read_text())
 cards=''.join(f'<a class="rank" href="../manuscripts/rank{r}.pdf"><span>Rank {r}</span><strong>{v["bound"]:,}</strong><small>complete multiplicity bound</small><b>{v["classes"]:,} classes</b><em>Read companion ↗</em></a>' for r,v in d['ranks'].items())
 initial=''.join('<tr><th scope="row">'+str(m)+'</th>'+''.join('<td>'+ (f'{v["counts"][str(m)]:,}' if str(m) in v['counts'] else '<span class="missing" aria-label="Not completely enumerated">—</span>')+'</td>' for v in d['ranks'].values())+'</tr>' for m in range(1,21))
 template='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Complete, independently verified counts of based fusion rings at ranks 3–8."><title>Fusion Ring Census</title>
<style>
:root{--ink:#193633;--muted:#64726b;--accent:#246b56;--paper:#f7f8f4;--line:#dce3d9;--white:#fff}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--accent);text-underline-offset:4px}a:hover{color:#103b2f}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #aa713a;outline-offset:4px}.wrap{max-width:1080px;padding:0 32px;margin:auto}.skip{position:absolute;left:-9999px}.skip:focus{left:16px;top:8px;background:white;padding:8px;z-index:10}header{border-bottom:1px solid var(--line);background:var(--white)}nav{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 0}.brand{font-weight:750;font-size:14px;letter-spacing:.08em;text-decoration:none;color:var(--ink)}.nav{display:flex;flex-wrap:wrap;gap:22px;font-size:13px}.nav a{text-decoration:none}.hero{padding:56px 0 30px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:.18em;color:var(--accent);text-transform:uppercase}h1{font:normal clamp(38px,5vw,58px)/1.1 Georgia,serif;letter-spacing:-.035em;margin:12px 0 18px}.hero p{font-size:17px;max-width:760px;color:var(--muted);margin:0}.meta{display:flex;gap:26px;margin:24px 0 0;font-size:13px;color:var(--muted)}.meta strong{color:var(--ink)}h2{font:normal 28px/1.25 Georgia,serif;margin:0 0 10px}.intro{display:flex;justify-content:space-between;gap:25px;align-items:end;margin:25px 0 18px}.intro p,.small{color:var(--muted);font-size:13px;margin:0}.download{white-space:nowrap;font-size:13px}.tablebox{background:var(--white);border:1px solid var(--line);border-radius:10px;overflow:hidden}.controls{padding:17px 22px;display:flex;align-items:end;gap:14px;flex-wrap:wrap;border-bottom:1px solid var(--line)}label{display:grid;gap:5px;font-size:11px;font-weight:650;color:var(--muted)}input,select,button{font:inherit;font-size:13px;padding:8px 11px;border:1px solid #cbd5cb;border-radius:5px;background:white;color:var(--ink)}input{width:92px}button{background:var(--accent);color:white;border-color:var(--accent);cursor:pointer}#status{margin-left:auto;font-size:12px;color:var(--muted)}.scroll{overflow:auto;max-height:810px}table{border-collapse:separate;border-spacing:0;width:100%;font-size:14px;font-variant-numeric:tabular-nums}th,td{padding:11px 20px;text-align:right;white-space:nowrap;border-bottom:1px solid #eef1ec}thead th{background:#eef3ed;position:sticky;top:0;z-index:1;color:#315347;font-weight:650;font-size:12px}tbody th{text-align:left;font-weight:500;color:var(--muted)}thead th:first-child{text-align:left}tbody tr:nth-child(even){background:#fafbf8}tbody tr:hover{background:#f0f6ed}.missing{color:#bcc5bc}.note{padding:15px 22px;font-size:12px;color:var(--muted);border-top:1px solid var(--line)}.coverage{margin:48px 0}.ranks{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}.rank{display:grid;background:white;border:1px solid var(--line);border-radius:8px;padding:22px;text-decoration:none}.rank span{font-size:12px;letter-spacing:.06em;text-transform:uppercase}.rank strong{font:normal 38px/1.2 Georgia,serif;margin:8px 0 0;color:var(--ink)}.rank small{font-size:11px;color:var(--muted)}.rank b{font-size:14px;font-weight:500;margin:15px 0 8px;color:var(--ink)}.rank em{font-size:12px;font-style:normal}.reading{display:grid;grid-template-columns:1fr 1fr;gap:42px;border-top:1px solid var(--line);padding:35px 0 45px}.reading p{font-size:14px;color:var(--muted)}.reading h2{font-size:25px}code{font:12px/1.7 ui-monospace,monospace}pre{background:#eaf0e7;border:1px solid var(--line);padding:16px;border-radius:7px;overflow:auto}footer{border-top:1px solid var(--line);padding:22px 0;font-size:12px;color:var(--muted)}.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}@media(max-width:650px){.wrap{padding:0 18px}nav{align-items:start;flex-direction:column;gap:10px}.nav{gap:15px}.hero{padding-top:35px}.meta{gap:13px;flex-wrap:wrap}.intro{align-items:start;flex-direction:column;gap:10px}th,td{padding:10px 14px}.controls{padding:14px}#status{width:100%;margin:0}.ranks{grid-template-columns:repeat(2,1fr)}.reading{grid-template-columns:1fr;gap:20px}.rank{padding:18px}}
</style></head><body><a class="skip" href="#counts">Skip to census table</a><header><div class="wrap"><nav aria-label="Main navigation"><a class="brand" href="../README.md">FUSION RING CENSUS</a><div class="nav"><a href="#counts">Counts</a><a href="#coverage">Companions</a><a href="REPRODUCIBILITY.md">Reproduce</a><a href="../verification/README.md">Evidence</a><a href="../oeis/README.md">OEIS</a></div></nav></div></header>
<main class="wrap"><section class="hero"><div class="eyebrow">Exact enumeration · ranks 3–8</div><h1>A census of fusion rings.</h1><p>Complete bounded counts, full multiplication tensors and mathematical companions. Every duality type is included, with no categorifiability filter.</p><div class="meta"><span><strong>@@TOTAL@@</strong> distinct classes</span><span><strong>6</strong> mathematical companions</span><span>Independent tensor verification</span></div></section>
<section id="counts" aria-labelledby="table-title"><div class="intro"><div><h2 id="table-title">Counts by rank and multiplicity</h2><p id="explanation">Number of based-isomorphism classes at exactly multiplicity m.</p></div><a class="download" href="../results/counts.csv" download>Download all counts · CSV ↓</a></div><div class="tablebox"><form class="controls" id="filters"><label>From multiplicity<input id="from" type="number" min="1" max="1000" value="1" required></label><label>Through multiplicity<input id="through" type="number" min="1" max="1000" value="20" required></label><label>Counting convention<select id="mode"><option value="exact">Exact multiplicity</option><option value="cumulative">At most this multiplicity</option></select></label><button type="submit">Show counts</button><span id="status" role="status" aria-live="polite">Multiplicities 1–20</span></form><div class="scroll" tabindex="0" role="region" aria-label="Census counts; scroll for more rows or columns"><table aria-describedby="explanation"><thead><tr><th scope="col">Multiplicity</th><th scope="col">Rank 3</th><th scope="col">Rank 4</th><th scope="col">Rank 5</th><th scope="col">Rank 6</th><th scope="col">Rank 7</th><th scope="col">Rank 8</th></tr></thead><tbody id="rows">@@ROWS@@</tbody></table></div><div class="note">A dash means the whole rank has not been completely enumerated at that bound. It never means zero. All values come from the <a href="../results/census.json">certified manifest</a>.</div></div></section>
<section class="coverage" id="coverage"><h2>Complete datasets & companions</h2><p class="small">Each bound includes every multiplicity up to that value. Click a rank to read its mathematical companion.</p><div class="ranks">@@CARDS@@</div></section>
<section class="reading"><div><h2>Reproduce and verify</h2><p>Run one complete bounded census on your own computer, with no clock limit. The launcher independently checks every tensor and the known count prefix before packaging a result.</p><pre><code>python3 scripts/run_laptop.py --rank 7 --bound 5</code></pre><a href="REPRODUCIBILITY.md">Setup, supported bounds and verification →</a></div><div><h2>Know what is being counted</h2><p>These are based rings, not fusion categories. Independent checking proves validity and uniqueness of the output; complete coverage also requires the mathematical search argument and normal completion of every duality stratum.</p><p><a href="../methods/completeness.md">Coverage arguments</a> · <a href="../verification/README.md">Verification records</a><br><a href="../audit/README.md">Reference database audit</a> · <a href="../oeis/README.md">OEIS drafts</a></p></div></section></main>
<footer><div class="wrap foot"><span>Sébastien Palcoux · BIMSA · Release @@DATE@@</span><span><a href="../CITATION.cff">Cite</a> · <a href="../NOTICE.md">Attribution & licensing</a></span></div></footer>
<script id="census-data" type="application/json">@@DATA@@</script><script>
const census=JSON.parse(document.getElementById('census-data').textContent),form=document.getElementById('filters'),status=document.getElementById('status');
form.addEventListener('submit',event=>{event.preventDefault();const first=Number(document.getElementById('from').value),last=Number(document.getElementById('through').value),cumulative=document.getElementById('mode').value==='cumulative';if(!Number.isInteger(first)||!Number.isInteger(last)||first<1||last>1000||last<first){status.textContent='Choose an increasing range from 1 to 1000.';return;}const sums={};for(const [rank,data] of Object.entries(census.ranks)){let total=0;sums[rank]={};for(let m=1;m<=data.bound;m++){total+=data.counts[m];sums[rank][m]=total;}}const body=document.getElementById('rows');body.replaceChildren();for(let m=first;m<=last;m++){const tr=document.createElement('tr'),th=document.createElement('th');th.scope='row';th.textContent=String(m);tr.append(th);for(let rank=3;rank<=8;rank++){const td=document.createElement('td'),value=(cumulative?sums[rank]:census.ranks[rank].counts)[m];td.textContent=value===undefined?'—':value.toLocaleString('en-US');if(value===undefined){td.className='missing';td.setAttribute('aria-label','Not completely enumerated');}tr.append(td);}body.append(tr);}document.getElementById('explanation').textContent=cumulative?'Number of based-isomorphism classes at multiplicity at most m.':'Number of based-isomorphism classes at exactly multiplicity m.';status.textContent=`Multiplicities ${first}–${last}`;});
</script></body></html>'''
 template=template.replace('@@TOTAL@@',f'{d["total_classes"]:,}').replace('@@DATE@@',html.escape(d['release_date'])).replace('@@ROWS@@',initial).replace('@@CARDS@@',cards).replace('@@DATA@@',json.dumps(d,separators=(',',':')))
 template=re.sub(r'href="([^"#][^"]*)"',lambda m: 'href="https://github.com/sebastienpalcoux/fusion-ring-census/blob/main/'+posixpath.normpath(posixpath.join('docs',m[1]))+'"',template)
 (ROOT/'docs/index.html').write_text(template);print('Built standalone census viewer.')
if __name__=='__main__':main()
